from datetime import date; from decimal import Decimal; from src.ledger import Account, AccountType, Direction, JournalEntry, JournalLine
class TestAccountsRouterCoverage:
    async def test_delete_account_with_transactions(self, client, db, test_user): 'AC-ledger.10.2'; account = Account(user_id=test_user.id, name='Cash', type=AccountType.ASSET, currency='USD'); db.add(account); await db.flush(); entry = JournalEntry(user_id=test_user.id, entry_date=date(2024, 1, 1), memo='Test transaction'); db.add(entry); await db.flush(); line = JournalLine(journal_entry_id=entry.id, account_id=account.id, direction=Direction.DEBIT, amount=Decimal('100.00'), currency='USD'); db.add(line); await db.commit(); await db.refresh(account); response = await client.delete(f'/accounts/{account.id}'); assert response.status_code == 400; assert 'transactions' in response.json()['detail'].lower()
